app.MapGet("/api/invoices/{id}", async (int id, AppDbContext db, IAuthorizationService auth, HttpContext ctx) =>
{
    var invoice = await db.Invoices.FindAsync(id);
    if (invoice == null) return Results.NotFound();

    var result = await auth.AuthorizeAsync(ctx.User, invoice, "InvoiceOwnerPolicy");
    if (!result.Succeeded) return Results.Forbid();

    return Results.Ok(invoice);
});

